import subprocess,sys
def run(fstr, opt="--filters"):
    p=subprocess.run(["/workspace/executable",opt+"="+fstr,"-c","/tmp/probe-fsyntax/text.txt"],capture_output=True)
    err=p.stderr.decode()
    lines=[l for l in err.split("\n") if l]
    pre="/workspace/executable: "
    body=[l[len(pre):] if l.startswith(pre) else l for l in lines]
    if p.returncode==0:
        return (0,None,None)
    # find caret line
    idx=None; msg=None
    for i,l in enumerate(body):
        if l.strip()=="^":
            idx=len(l)-1
            msg=body[i+1] if i+1<len(body) else None
    return (p.returncode, idx, msg, body)
for f in sys.argv[1:]:
    r=run(f)
    print(repr(f), "->", r[0], "caret_col=", r[1], "msg=", r[2])
